#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
#include <string>
#include <vector>

// What the middleware holds for one subscription under KeepLast(depth): the newest `depth`
// messages, plus a count of the older ones it dropped to keep them.
class Inbox {
 public:
  Inbox(std::string topic, std::ptrdiff_t depth) : topic_(std::move(topic)), depth_(depth) {}

  void deliver(std::int64_t seq) {
    ++delivered_;
    if (std::ssize(waiting_) == depth_) {
      waiting_.pop_front();
      ++dropped_;
    }
    waiting_.push_back(seq);
  }

  // The wait set carries one flag per subscription: work or no work, never how much.
  [[nodiscard]] bool ready() const { return !waiting_.empty(); }

  std::int64_t take() {
    const std::int64_t seq = waiting_.front();
    waiting_.pop_front();
    return seq;
  }

  [[nodiscard]] const std::string& topic() const { return topic_; }

  [[nodiscard]] std::string report() const {
    return std::format("{}: {} delivered, {} dropped, {} waiting", topic_, delivered_, dropped_,
                       std::ssize(waiting_));
  }

 private:
  std::string topic_;
  std::ptrdiff_t depth_;
  std::deque<std::int64_t> waiting_;
  std::int64_t delivered_ = 0;
  std::int64_t dropped_ = 0;
};

int main() {
  std::vector<Inbox> inboxes{Inbox{"odom", 10}, Inbox{"scan", 5}};
  Inbox& odom = inboxes.front();
  Inbox& scan = inboxes.back();

  for (std::int64_t seq = 1; seq <= 100; ++seq) odom.deliver(seq);
  for (std::int64_t seq = 1; seq <= 20; ++seq) scan.deliver(seq);
  std::cout << odom.report() << "\n" << scan.report() << "\n";

  // The thread is free again. Each pass over the wait set takes at most one message per subscription.
  std::string order;
  for (int pass = 0; pass < 3; ++pass) {
    for (Inbox& inbox : inboxes) {
      if (!inbox.ready()) continue;
      if (!order.empty()) order += ", ";
      order += std::format("{} {}", inbox.topic(), inbox.take());
    }
  }
  std::cout << std::format("three passes over the wait set: {}\n", order);
}

#include <algorithm>
#include <atomic>
#include <chrono>
#include <format>
#include <memory>
#include <string>

#include <example_interfaces/srv/trigger.hpp>
#include <geometry_msgs/msg/twist.hpp>
#include <nav_msgs/msg/odometry.hpp>
#include <rclcpp/rclcpp.hpp>

using namespace std::chrono_literals;

// Limits how much the commanded speed may change in one control step. No ROS and no clock in here,
// so a test drives it directly. The two speeds travel in a struct, so they can't be swapped.
class Ramp {
 public:
  struct Step {
    double from;
    double to;
  };

  explicit Ramp(double max_change_per_step) : max_change_(max_change_per_step) {}

  [[nodiscard]] double next(Step step) const {
    return step.from + std::clamp(step.to - step.from, -max_change_, max_change_);
  }

 private:
  double max_change_;
};

class Relay : public rclcpp::Node {
 public:
  using Trigger = example_interfaces::srv::Trigger;

  explicit Relay(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("relay", options) {
    control_ = create_callback_group(rclcpp::CallbackGroupType::MutuallyExclusive);
    checks_ = create_callback_group(rclcpp::CallbackGroupType::MutuallyExclusive);

    rclcpp::SubscriptionOptions subscription_options;
    subscription_options.callback_group = control_;
    odometry_ = create_subscription<nav_msgs::msg::Odometry>(
        "odom", rclcpp::QoS(rclcpp::KeepLast(10)),
        [this](const nav_msgs::msg::Odometry& msg) { measured_ = msg.twist.twist.linear.x; },
        subscription_options);

    publisher_ = create_publisher<geometry_msgs::msg::Twist>("cmd_vel", rclcpp::QoS(rclcpp::KeepLast(10)));
    timer_ = create_timer(50ms, [this] { step(); }, control_);

    service_ = create_service<Trigger>(
        "~/self_test",
        [this](const std::shared_ptr<Trigger::Request>, std::shared_ptr<Trigger::Response> response) {
          response->message = self_test();
          response->success = true;
        },
        rclcpp::ServicesQoS(), checks_);
  }

 private:
  // Runs in `control_`, so it never overlaps itself and never runs beside the odometry callback.
  void step() {
    commanded_ = ramp_.next({.from = commanded_, .to = target_});
    geometry_msgs::msg::Twist command;
    command.linear.x = commanded_;
    publisher_->publish(command);
  }

  // Runs in `checks_`, on another thread, while the control loop keeps its 20 Hz.
  [[nodiscard]] std::string self_test() const {
    return std::format("measured {:.3f} m/s", measured_.load());
  }

  Ramp ramp_{0.05};  // 0.05 m/s per 50 ms step is 1 m/s^2
  double target_ = 0.4;
  double commanded_ = 0.0;        // only `control_` touches this one
  std::atomic<double> measured_;  // written in `control_`, read in `checks_`

  rclcpp::CallbackGroup::SharedPtr control_;
  rclcpp::CallbackGroup::SharedPtr checks_;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odometry_;
  rclcpp::Publisher<geometry_msgs::msg::Twist>::SharedPtr publisher_;
  rclcpp::TimerBase::SharedPtr timer_;
  rclcpp::Service<Trigger>::SharedPtr service_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::executors::MultiThreadedExecutor executor;
  const auto node = std::make_shared<Relay>();
  executor.add_node(node);
  executor.spin();
  rclcpp::shutdown();
}

#include <memory>

#include <example_interfaces/srv/trigger.hpp>
#include <rclcpp/rclcpp.hpp>

class AnswerServer : public rclcpp::Node {
 public:
  using Trigger = example_interfaces::srv::Trigger;

  explicit AnswerServer(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("answer_server", options) {
    service_ = create_service<Trigger>(
        "/self_test", [this](const std::shared_ptr<Trigger::Request>, std::shared_ptr<Trigger::Response> response) {
          RCLCPP_INFO(get_logger(), "request received, answering");
          response->success = true;
          response->message = "all good";
        });
  }

 private:
  rclcpp::Service<Trigger>::SharedPtr service_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<AnswerServer>());
  rclcpp::shutdown();
}

#include <chrono>
#include <future>
#include <memory>
#include <string>

#include <example_interfaces/srv/trigger.hpp>
#include <rclcpp/rclcpp.hpp>

using namespace std::chrono_literals;

class BlockingClient : public rclcpp::Node {
 public:
  using Trigger = example_interfaces::srv::Trigger;

  explicit BlockingClient(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("blocking_client", options) {
    const std::string grouping = declare_parameter<std::string>("grouping", "shared");
    multi_threaded_ = declare_parameter<bool>("multi_threaded", false);

    if (grouping == "reentrant") {
      client_group_ = create_callback_group(rclcpp::CallbackGroupType::Reentrant);
      timer_group_ = client_group_;
    } else {
      client_group_ = create_callback_group(rclcpp::CallbackGroupType::MutuallyExclusive);
      timer_group_ = grouping == "separate"
                         ? create_callback_group(rclcpp::CallbackGroupType::MutuallyExclusive)
                         : client_group_;
    }

    client_ = create_client<Trigger>("/self_test", rclcpp::ServicesQoS(), client_group_);
    timer_ = create_timer(1s, [this] { ask(); }, timer_group_);
    RCLCPP_INFO(get_logger(), "grouping %s, multi_threaded %s", grouping.c_str(),
                multi_threaded_ ? "true" : "false");
  }

  [[nodiscard]] bool multi_threaded() const { return multi_threaded_; }

 private:
  // Waiting here is the bug the exercise reproduces. Real code passes a callback instead.
  void ask() {
    if (!client_->service_is_ready()) {
      RCLCPP_WARN(get_logger(), "no server yet");
      return;
    }
    RCLCPP_INFO(get_logger(), "sending request");
    auto sent = client_->async_send_request(std::make_shared<Trigger::Request>());
    if (sent.wait_for(5s) == std::future_status::ready) {
      RCLCPP_INFO(get_logger(), "answer: %s", sent.get()->message.c_str());
    } else {
      RCLCPP_WARN(get_logger(), "no answer within 5 s");
      client_->remove_pending_request(sent.request_id);
    }
  }

  bool multi_threaded_ = false;
  rclcpp::CallbackGroup::SharedPtr client_group_;
  rclcpp::CallbackGroup::SharedPtr timer_group_;
  rclcpp::Client<Trigger>::SharedPtr client_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  const auto node = std::make_shared<BlockingClient>();
  if (node->multi_threaded()) {
    rclcpp::executors::MultiThreadedExecutor executor;
    executor.add_node(node);
    executor.spin();
  } else {
    rclcpp::spin(node);
  }
  rclcpp::shutdown();
}

CallbackReturn on_activate(const rclcpp_lifecycle::State& state) override {
  LifecycleNode::on_activate(state);  // activates the managed publishers
  timer_->reset();                    // the timer is yours to start
  return CallbackReturn::SUCCESS;
}
